--ENB CONFIGURATION
exec('set_enb id=1 plmn=311:489 s1='..ENB1_S1_ADDR..' enb_id_macro=0x00001 daemon='..DAEMON_IP..':'..EDAEMON_PORT..' x2='..ENB_X2U_ADDR..' x2u='..ENB_X2U_ADDR..' type=simulated x2_peers=none xp_management=on xp='..ENB1_X2_ADDR..':32742 xpu='..ENB1_X2_ADDR..':32742 local_crm=on')
