--UEC CONFIGURATION
exec('set_uec id=1 ip='..DAEMON_IP..':'..EDAEMON_PORT..' peer='..DAEMON_IP..':2152 retries=unlimited gtpu=off pdn=1 devtype=tun devname=tunUEC addr=72.22.0.1/26 proxy_snd_buf_size=20971520 proxy_rcv_buf_size=20971520 proxy_read_packets_threshold=20')

--UE CONFIGURATION
for ue_id=1,NUMBER_OF_UES_SA do
    local ue_id_aligned
    if (ue_id>0 and ue_id<10) then ue_id_aligned = '0'..ue_id
    elseif (ue_id>=10 and ue_id<100) then ue_id_aligned = ue_id
    end
    print(ue_id_aligned)
    exec('set_ue simulated id='..ue_id..' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00 opc_key=0ED47545168EAFE2C39C075829A7B61F'..
         ' nia=null+zuc+aes+snow3g nea=null+zuc+aes+snow3g suci=0:311:489:0000:0:0:0216454'..ue_id_aligned..' mode=nr enb=2 cell=3')
    exec('ue_param id='..ue_id..' ue_nr_capabilities='..NR_UE_CAP_4CC..'')
    exec('set_pdu_param ue='..ue_id..' pdu=1 trf_type=internal')
end

for ue_id=NUMBER_OF_UES_SA+1,NUMBER_OF_UES_NSA+NUMBER_OF_UES_SA do
    local imsi_prefix = '311:489:216455'
    local ue_id_aligned
                if (ue_id>0 and ue_id<10) then ue_id_aligned = '0'..ue_id
                elseif (ue_id>=10 and ue_id<100) then ue_id_aligned = ue_id
                end
                local imsi = imsi_prefix..ue_id_aligned

    exec('set_ue simulated id='..ue_id..' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00'..
         ' nia=aes+zuc+snow3g+null nea=aes+zuc+snow3g+null'..' imsi='..imsi)
    exec('ue_param id='..ue_id..' ue_nr_capabilities='..NSA_S23_UE_CAPA..' dual_conn=eutra_nr ue_eutra_nr_capabilities='..NR_EUTRA_S23_CAPA..'')
    exec('set_bearer id=2 ue='..ue_id..' qci=9 pdn=1 ip=4.7.254.'..ue_id..' default=on ul_nat_gw=10.0.2.1 dl_nat_gw=10.0.2.1 trf_type=internal')
end

